int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (!ctx || !gb) {
        return 0;
    }

    if (get_bits_left(gb) < 0) {
        return 0;
    }

    ctx->frame_type = 0;
    ctx->dct_type = 0;

    skip_bits(gb, 3);
    skip_bits(gb, 1);

    int temporal_reference = get_bits(gb, 10);
    int vop_structure = get_bits(gb, 1);
    int picture_type = get_bits(gb, 2);

    if (picture_type == 0) {
        ctx->predictor_reset = 1;
    }

    if (picture_type == 1 || picture_type == 2) {
        ctx->scanning_table_configured = 1;
    }

    for (int i = 0; i < 8; i++) {
        ctx->default_matrices[i] = get_bits(gb, 8);
    }

    while (get_bits_left(gb) > 0) {
        int user_data = get_bits(gb, 8);
        if (user_data == 0) {
            break;
        }
        // Process user data
    }

    return 0;
}
